using System;using UnityEngine;
public static class NextFourPartsValidation{
 static void Check(bool c,string message){if(!c)throw new Exception("Next-four golden failed: "+message);}
 public static void Run(){byte[] b={1,2,3};string h=SourcePartsScene.Hash(b);SourcePartsScene.RequireHash(b,h);b[0]=4;bool rejected=false;try{SourcePartsScene.RequireHash(b,h);}catch{rejected=true;}Check(rejected,"source hash corruption rejected");var manifest=JsonUtility.FromJson<CatalogManifest>(Resources.Load<TextAsset>("Catalog/manifest").text);int count=0;foreach(var item in manifest.items){if(!(item.id.StartsWith("sourceparts-cell-")||item.id.StartsWith("sourceparts-dna-")||item.id.StartsWith("sourceparts-machine-")||item.id.StartsWith("sourceparts-origami-")))continue;count++;var go=new GameObject("NEXTFOUR EDITOR SYNTHETIC");try{var scene=go.AddComponent<CatalogScene>();scene.Configure(item);var parts=go.GetComponent<SourcePartsScene>();Check(parts.pivots.Count==(parts.config.topic=="cell"?3:2),"true independent identities");parts.Sample();for(int i=0;i<parts.pivots.Count;i++)Check(Vector3.Distance(parts.pivots[i].localPosition,parts.Pixel(parts.config.parts[i].centroid[0],parts.config.parts[i].centroid[1]))<1e-6f,"source centroid zero-state");bool flat=parts.flat;scene.Spring();Check(parts.flat!=flat,"scene mode binding");scene.Tap();Check(parts.playing,"scene play binding");scene.ControlAxes(Vector2.zero,Vector2.right,1,"editor-synthetic");Check(parts.parameter==.5f,"parameter binding");parts.time=2;parts.Sample();Check(parts.label.text.Contains("not learned rig/calibration"),"scene UI honesty");string topic=parts.config.topic;
 if(topic=="cell")Check(parts.pivots[1].localPosition.z<-.001f&&parts.pivots[2].localPosition.z<-.001f,"actual compartment explode");
 if(topic=="dna")Check(parts.pivots[0].localPosition.x<parts.Pixel(parts.config.parts[0].centroid[0],parts.config.parts[0].centroid[1]).x&&parts.pivots[1].localPosition.x>parts.Pixel(parts.config.parts[1].centroid[0],parts.config.parts[1].centroid[1]).x,"two visible strands separate no bonds");
 if(topic=="machine"){for(int i=0;i<2;i++){var p=parts.config.parts[i];var m=p.host_basis;var n=p.source_face_normal;var mapped=new Vector3(m[0]*n[0]+m[1]*n[1]+m[2]*n[2],m[3]*n[0]+m[4]*n[1]+m[5]*n[2],-(m[6]*n[0]+m[7]*n[1]+m[8]*n[2]));Check(Vector3.Distance(mapped,Vector3.back)<1e-5f,"independent PCA-front before Unity reflection");}var q=parts.pivots[0].localRotation*parts.pivots[1].localRotation;Check(Quaternion.Angle(q,Quaternion.identity)<1e-3f,"opposite equal authored gears");}
 if(topic=="origami"){Check(Quaternion.Angle(parts.pivots[0].localRotation,Quaternion.identity)>40,"actual panel authored edge fold");Check(parts.config.parts[1].fallback,"right source RGBA honest fallback");}
 scene.Tap();Check(!parts.playing,"pause binding");scene.Reset();parts.Sample();Check(parts.time==0&&parts.parameter==0&&!parts.playing,"reset binding");}finally{UnityEngine.Object.DestroyImmediate(go);}}Check(count==8,"eight source views");Debug.Log("NEXTFOUR GOLDEN PASS: source corruption/source-centroid/PCA-front/actual scene dispatch/UI; editor-synthetic, no physical acceptance");}
}
